def clean_duplicate_user_data(apps, schema_editor):
    User = apps.get_model("niqabaty", "User")
    manager = User._base_manager

    # 1. Clean empty strings and whitespace
    for user in manager.all():
        modified = False
        if user.email == "":
            user.email = None
            modified = True
        elif user.email:
            cleaned_email = user.email.strip().lower()
            if user.email != cleaned_email:
                user.email = cleaned_email
                modified = True
                
        if user.phone_number == "":
            user.phone_number = None
            modified = True
        elif user.phone_number:
            cleaned_phone = user.phone_number.strip()
            if user.phone_number != cleaned_phone:
                user.phone_number = cleaned_phone
                modified = True
                
        if modified:
            user.save()

    # 2. Resolve duplicate emails
    duplicate_emails = (
        manager.exclude(email=None)
        .values("email")
        .annotate(email_count=Count("email"))
        .filter(email_count__gt=1)
    )

    for entry in duplicate_emails:
        email_val = entry["email"]
        users = manager.filter(email=email_val).order_by("id")
        for user in users[1:]:
            parts = email_val.split("@")
            if len(parts) == 2:
                new_email = f"{parts[0]}+dup{user.id}@{parts[1]}"
            else:
                new_email = f"{email_val}_dup{user.id}"
            user.email = new_email
            user.save()

    # 3. Resolve duplicate phone numbers
    duplicate_phones = (
        manager.exclude(phone_number=None)
        .values("phone_number")
        .annotate(phone_count=Count("phone_number"))
        .filter(phone_count__gt=1)
    )

    for entry in duplicate_phones:
        phone_val = entry["phone_number"]
        users = manager.filter(phone_number=phone_val).order_by("id")
        for user in users[1:]:
            user.phone_number = f"{phone_val}_dup{user.id}"
            user.save()


